6.29 以二叉链表为存储结构，一算法对二叉树进行层次遍历(层次遍历的定义见6.13).提示：应使用队列来保存各层的结点。   答：  　#define M 100 //假设结点数最多为100 　typedef char DataType;//队列结点值类型 　typedef struct//定义一个队列 　　{ 　　　int front; 　　　int rear; 　　　int count; 　　　DataType data[M]; 　　}QBTree;  　static QBTree Q;//设一全局静态变量保存遍历结果 　void Levelorder(BinTree T) 　　{//层次遍历 　　　if(T) 　　　　{ 　　　　　if(QueueEmpty(&Q)) 　　　　　　{ //根结点及子树结点入队 　　　　　　　EnQueue(&Q,T->data); 　　　　　　　if(T->lchild) 　　　　　　　　EnQueue(&Q,T->lchild->data); 　　　　　　　if(T->rchild) 　　　　　　　　EnQueue(&Q,T->rchild->data); 　　　　　　} 　　　　　else 　　　　　　{ //子树结点入队 　　　　　　　if(T->lchild) 　　　　　　　　EnQueue(&Q,T->lchild->data); 　　　　　　　if(T->rchild) 　　　　　　　　EnQueue(&Q,T->rchild->data); 　　　　　　} 　　　　　Levelorder(T->lchild);//遍历左子树 　　　　　Levelorder(T->rchild);//遍历右子树 　　　　} 　　}
