	1、请写出二叉树的中序非递归遍历的基本思想，然后写出算法，实现对二叉树的中序非递归遍历。
基本思想：根据中序遍历的顺序，对于任一结点，优先访问其左孩子，而左孩子结点又可以看做一根结点，然后继续访问其左孩子结点，直到遇到左孩子结点为空的结点才进行访问，然后按相同的规则访问其右子树。因此其处理过程如下：

   对于任一结点P，
  1)若其左孩子不为空，则将P入栈并将P的左孩子置为当前的P，然后对当前结点P再进行相同的处理；
  2)若其左孩子为空，则取栈顶元素并进行出栈操作，访问该栈顶结点，然后将当前的P置为栈顶结点的右孩子；
  3)直到P为NULL并且栈为空则遍历结束
/* c6-2.h 二叉树的二叉链表存储表示 */
 typedef struct BiTNode
 {
   TElemType data;
   struct BiTNode *lchild,*rchild; /* 左右孩子指针 */
 }BiTNode,*BiTree;
Status InOrderTraverse2(BiTree T,Status(*Visit)(TElemType))
 { /* 采用二叉链表存储结构，Visit是对数据元素操作的应用函数。算法6.2 */
   /* 中序遍历二叉树T的非递归算法(利用栈)，对每个数据元素调用函数Visit */
   SqStack S;
   BiTree p;
   InitStack(&S);
   Push(&S,T); /* 根指针进栈 */
   while(!StackEmpty(S))
   {
     while(GetTop(S,&p)&&p)
       Push(&S,p->lchild); /* 向左走到尽头 */
     Pop(&S,&p); /* 空指针退栈 */
     if(!StackEmpty(S))
     { /* 访问结点,向右一步 */
       Pop(&S,&p);
       if(!Visit(p->data))
         return ERROR;
       Push(&S,p->rchild);
     }
   }
   printf("\n");
   return OK;
 }
