//stack.h头文件

#include <stdio.h>
#include <malloc.h>
#include <stdlib.h>

#define STACKSIZE 50
#define STACKINCREMENT 20
#define OVERFLOW -1
#define OK 1
#define ERROR -1

typedef struct
{
int *base;
int *top;
int stacksize;
}Stack;

int InitStack(Stack &s) //创建一个空栈
{
s.base=(int*)malloc(STACKSIZE*sizeof(int));
if(!s.base)
   return (OVERFLOW);
s.top=s.base;
s.stacksize=STACKSIZE;
return (OK);
}

int Push(Stack &s,int e)
{
if((s.top-s.base)>s.stacksize)
{
   s.base=(int*)realloc(s.base,(STACKSIZE+STACKINCREMENT)*sizeof(int));
   if(!s.base)
    return(OVERFLOW);
   s.top=s.base+s.stacksize;
        s.stacksize+=STACKINCREMENT;
}
*s.top++=e;
return (OK);
}

bool Empty(Stack s)
{
if(s.base==s.top)
   return true;
else
   return false;
}

int Pop(Stack &s)
{
int e;
e=*--s.top;
return e;
}
