}Graph;

int LocateVex(Graph G,int v)    //返回节点v在图中的位置
{
int i;
for(i=0;i<G.vexnum;++i)
   if(G.vertices[i].data==v)
     break;
   else
    continue;
if(i<G.vexnum)
