}

int NextAdjVex(Graph G,int v,int w) //返回v中相对于w的下一个邻接顶点
{
int flag=0;
ArcNode *p;
p=G.vertices[v].firstarc;
while(p)
{
   if(p->adjvex==w)
   {
    flag=1;
    break;
   }
   p=p->nextarc;
}
if(flag && p->nextarc)
   return p->nextarc->adjvex;
else
   return -1;
