bool Visited[MAX];

//深度优先遍历
void DFS(Graph G,int v)
{
Visited[v]=true;
    printf("v%d ",G.vertices[v].data);
int w;
for(w=FirstAdjVex(G,v);w>=0;w=NextAdjVex(G,v,w))
   if(!Visited[w])
    DFS(G,w);
}

void DFSTraverse(Graph G)
{
int v;
for(v=0;v<G.vexnum;++v)
   Visited[v]=false;
for(v=0;v<G.vexnum;++v)
   if(!Visited[v])
    DFS(G,v);       //递归
}
