#include "graph.h"
#include "stack.h"

void TopologicalSort(Graph G) //拓扑排序函数
{
int i,j,k;
int count=0;    //用来统计顶点的个数
Stack s; //定义一个栈，用来保存入度为的顶点
InitStack(s); //初始化栈
for(i=0;i<G.vexnum;++i)
   if(G.vertices[i].indegree==0)    //若第i个顶点的入度为，i表示顶点在图中的位置
    Push(s,i);                  //将第i个顶点入栈
while(!Empty(s))
{
   j=Pop(s);       // 将为入度的顶点位置出栈，并保存到j中
   count++;        //统计顶点的个数
   printf("v%d ",G.vertices[j].data); //输出入度为的顶点
        ArcNode *p;
   for(p=G.vertices[j].firstarc; p ;p=p->nextarc)   //找与第j个顶点的邻接顶点，并将其入度减
   {
    k=p->adjvex;
    --(G.vertices[k].indegree);
    if(G.vertices[k].indegree==0)    //如果入度为,就入栈
     Push(s,k);
   }
}
if(count<G.vexnum)   //count小于顶点的个数时候，说明有环，不符合拓扑排序的要求
{
   printf("Error!\n图中有环!不是有向无环图!\n");
   exit(0);               //退出
}
}
